{
  "scenarios": [
    {
      "id": "E1-2-postings-positive-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-postings"
      },
      "category": "positive",
      "purpose": "Representar uma transação estruturada com valor zero, identificadores numéricos preservados e campos de caracteres vazios permitidos.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "dailyTransactions": [
            {
              "id": "0000000000000001",
              "typeCode": "01",
              "categoryCode": "0005",
              "source": "",
              "description": "",
              "amount": "0.00",
              "merchantId": "000000000",
              "merchantName": "",
              "merchantCity": "",
              "merchantZip": "",
              "cardNumber": "",
              "originalTimestamp": "",
              "processingTimestamp": "",
              "filler": ""
            }
          ],
          "transactionFile": "TRANFILE",
          "crossReferenceFile": "XREFFILE",
          "accountFile": "ACCTFILE",
          "categoryBalanceFile": "TCATBALF"
        }
      },
      "expectedFromContract": {
        "requestConformance": "O corpo satisfaz o schema. Valor zero e campos PIC X vazios são representáveis; campos de caracteres são preenchidos à direita com espaços.",
        "responses": [
          {
            "status": 200,
            "schema": "#/components/schemas/PostingResult",
            "obligations": [
              "Em conclusão normal, processedCount é 1.",
              "Uma rejeição de negócio não implica HTTP 500; se houver rejeição, o código de retorno COBOL é explicitamente 4.",
              "Caso a transação seja validada e escrita, processingTimestamp é substituído por CURRENT-DATE; o filler de entrada não é explicitamente copiado."
            ]
          },
          {
            "status": 500,
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "Representa falha de runtime ou caminho de terminação anormal.",
              "Não estabelece rollback nem ausência de efeitos persistentes."
            ]
          }
        ]
      },
      "limitations": [
        "Os identificadores de binding são valores candidatos opacos; não afirmam a existência de datasets nem constituem fixtures.",
        "A categoria positive indica conformidade da entrada, não garantia de postagem ou HTTP 200.",
        "Sem o estado externo, não é possível determinar se haverá rejeição nem seu motivo.",
        "Não são fixados timestamps gerados, bytes de saída ou mensagens diagnósticas."
      ]
    },
    {
      "id": "E1-2-postings-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-postings"
      },
      "category": "boundary",
      "purpose": "Cobrir o limite inferior do fluxo diário: nenhuma transação.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "dailyTransactions": [],
          "transactionFile": "TRANFILE",
          "crossReferenceFile": "XREFFILE",
          "accountFile": "ACCTFILE",
          "categoryBalanceFile": "TCATBALF"
        }
      },
      "expectedFromContract": {
        "requestConformance": "dailyTransactions vazio é explicitamente permitido.",
        "responses": [
          {
            "status": 200,
            "schema": "#/components/schemas/PostingResult",
            "obligations": [
              "processedCount e rejectedCount são 0.",
              "transactions e rejects são arrays vazios.",
              "diagnostics é um array de strings.",
              "Não há obrigação de returnCode igual a zero."
            ]
          },
          {
            "status": 500,
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "Falhas de abertura ou fechamento verificadas podem causar terminação anormal mesmo com entrada vazia.",
              "A resposta exige program e diagnostics."
            ]
          }
        ]
      },
      "limitations": [
        "Os bindings não foram provisionados nem consultados.",
        "Entrada vazia não elimina as precondições de arquivos.",
        "TRANFILE é aberto como OUTPUT; não se infere preservação de histórico nem ausência de efeitos sobre o arquivo."
      ]
    },
    {
      "id": "E1-2-postings-negative-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-postings"
      },
      "category": "negative",
      "purpose": "Representar violação do envelope pela ausência do campo obrigatório dailyTransactions.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactionFile": "TRANFILE",
          "crossReferenceFile": "XREFFILE",
          "accountFile": "ACCTFILE",
          "categoryBalanceFile": "TCATBALF"
        }
      },
      "expectedFromContract": {
        "requestConformance": "O corpo não satisfaz o schema porque dailyTransactions é obrigatório.",
        "obligations": [
          "O contrato não especifica status HTTP nem schema de resposta para erro de validação do request.",
          "HTTP 500 é descrito para falha de execução ou terminação anormal, não como resposta obrigatória a esta omissão."
        ]
      },
      "limitations": [
        "Candidato deliberadamente inválido segundo o schema.",
        "Não é possível inferir se a camada de transporte rejeita a entrada antes da execução.",
        "Não se espera automaticamente HTTP 400 ou 422."
      ]
    },
    {
      "id": "E1-2-interest-positive-01",
      "operation": {
        "method": "POST",
        "path": "/interest-transactions"
      },
      "category": "positive",
      "purpose": "Representar uma invocação conforme usando o exemplo contratual de prefixo com dez caracteres.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "idPrefix": "2022071800",
          "categoryBalanceFile": "TCATBALF",
          "crossReferenceFile": "XREFFILE",
          "accountFile": "ACCTFILE",
          "disclosureGroupFile": "DISCGRP"
        }
      },
      "expectedFromContract": {
        "requestConformance": "idPrefix tem exatamente dez caracteres e não é interpretado como data.",
        "responses": [
          {
            "status": 200,
            "schema": "#/paths/~1interest-transactions/post/responses/200/content/application~1json/schema",
            "obligations": [
              "A resposta exige transactions, array de RawTransaction, e diagnostics, array de strings.",
              "Se houver transações geradas, seus IDs usam o prefixo fornecido seguido de contador de seis dígitos, inicialmente 000001.",
              "Uma taxa não zero gera transação mesmo quando o valor calculado é zero ou negativo.",
              "O último account não é explicitamente persistido ao final do loop.",
              "Saldos de categoria não são modificados e as transações geradas não são automaticamente postadas ou mescladas ao mestre."
            ]
          },
          {
            "status": 500,
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "Ausência de conta, referência cruzada ou disclosure padrão pode levar à terminação anormal.",
              "Artefatos e alterações persistentes podem preceder a falha."
            ]
          }
        ]
      },
      "limitations": [
        "Os bindings são apenas identificadores candidatos, sem afirmação de existência ou conteúdo.",
        "Não há campos de request para fornecer contas, taxas ou saldos inline.",
        "Não se determina quantidade, valor ou conteúdo bruto das transações geradas.",
        "Não se garante HTTP 200 nem returnCode zero."
      ]
    },
    {
      "id": "E1-2-interest-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/interest-transactions"
      },
      "category": "boundary",
      "purpose": "Cobrir prefixo formado por exatamente dez espaços e bindings vazios, ambos representáveis pelos schemas.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "idPrefix": "          ",
          "categoryBalanceFile": "",
          "crossReferenceFile": "",
          "accountFile": "",
          "disclosureGroupFile": ""
        }
      },
      "expectedFromContract": {
        "requestConformance": "O prefixo tem dez caracteres. DatasetBinding é string sem minLength; portanto, strings vazias não são excluídas pelo schema.",
        "responses": [
          {
            "status": 200,
            "schema": "#/paths/~1interest-transactions/post/responses/200/content/application~1json/schema",
            "obligations": [
              "Se houver geração, os dez espaços são o prefixo dos IDs; o parâmetro não sofre validação de calendário.",
              "transactions e diagnostics são obrigatórios; returnCode é opcional."
            ]
          },
          {
            "status": 500,
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "Falha observada de runtime é representada por ExecutionFailure.",
              "A ausência de artefatos parciais na resposta não demonstra ausência de escritas."
            ]
          }
        ],
        "obligations": [
          "A resolução de um binding não pode substituí-lo silenciosamente por um dataset vazio."
        ]
      },
      "limitations": [
        "Binding vazio não é prova de binding indisponível; sua resolução depende do ambiente.",
        "Não há garantia de sucesso ou de falha para estes identificadores.",
        "O request não permite selecionar explicitamente entrada vazia, conta única ou taxa zero."
      ]
    },
    {
      "id": "E1-2-interest-negative-01",
      "operation": {
        "method": "POST",
        "path": "/interest-transactions"
      },
      "category": "negative",
      "purpose": "Representar prefixo um caractere abaixo do comprimento obrigatório.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "idPrefix": "123456789",
          "categoryBalanceFile": "TCATBALF",
          "crossReferenceFile": "XREFFILE",
          "accountFile": "ACCTFILE",
          "disclosureGroupFile": "DISCGRP"
        }
      },
      "expectedFromContract": {
        "requestConformance": "O prefixo de nove caracteres viola minLength: 10.",
        "obligations": [
          "A ausência de verificação de PARM-LENGTH no programa não remove a restrição do schema HTTP.",
          "O contrato não define uma resposta HTTP específica para esta violação de request."
        ]
      },
      "limitations": [
        "Candidato deliberadamente inválido segundo o schema.",
        "Não se presume preenchimento automático do prefixo pela camada de transporte.",
        "Não se infere execução COBOL nem um status 4xx específico."
      ]
    },
    {
      "id": "E1-2-reports-positive-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-reports"
      },
      "category": "positive",
      "purpose": "Representar uma transação selecionável por intervalo inclusivo de caracteres não calendáricos em DATEPARM.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [
            {
              "id": "0000000000000001",
              "typeCode": "01",
              "categoryCode": "0005",
              "source": "",
              "description": "",
              "amount": "0.00",
              "merchantId": "000000000",
              "merchantName": "",
              "merchantCity": "",
              "merchantZip": "",
              "cardNumber": "",
              "originalTimestamp": "",
              "processingTimestamp": "0123456789",
              "filler": ""
            }
          ],
          "dateParameters": [
            "01234567890123456789012345678901234567890123456789012345678901234567890123456789"
          ],
          "crossReferenceFile": "CARDXREF",
          "transactionTypeFile": "TRANTYPE",
          "transactionCategoryFile": "TRANCATG"
        }
      },
      "expectedFromContract": {
        "requestConformance": "DATEPARM tem 80 caracteres. startDate é 0123456789, o caractere na posição 11 é ignorado e endDate é 1234567890. Não há validação de calendário.",
        "responses": [
          {
            "status": 200,
            "schema": "#/paths/~1transaction-reports/post/responses/200/content/application~1json/schema",
            "obligations": [
              "O processingTimestamp fornecido coincide com o limite inicial inclusivo.",
              "A resposta exige lines e diagnostics; cada linha emitida tem exatamente 133 caracteres, preservando espaços finais.",
              "A operação não modifica contas, saldos ou o mestre de transações.",
              "Os totais emitidos não são substituídos por agregados corrigidos."
            ]
          },
          {
            "status": 500,
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "INVALID KEY nas consultas de referência de cartão, tipo ou categoria pode provocar terminação anormal.",
              "partialReportLines, quando presente, contém linhas de 133 caracteres."
            ]
          }
        ]
      },
      "limitations": [
        "Os bindings não estabelecem a existência das referências necessárias.",
        "Não se determina conta associada ao cartão nem descrições de tipo e categoria.",
        "Não são fixadas linhas literais de relatório ou quantidade de linhas.",
        "A retenção do registro após EOF depende do runtime; não se garante total igual à soma dos detalhes."
      ]
    },
    {
      "id": "E1-2-reports-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-reports"
      },
      "category": "boundary",
      "purpose": "Cobrir DATEPARM vazio e fluxo de transações vazio sem inventar registros de parâmetro.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameters": [],
          "crossReferenceFile": "CARDXREF",
          "transactionTypeFile": "TRANTYPE",
          "transactionCategoryFile": "TRANCATG"
        }
      },
      "expectedFromContract": {
        "requestConformance": "Ambos os arrays podem ser vazios.",
        "responses": [
          {
            "status": 200,
            "schema": "#/paths/~1transaction-reports/post/responses/200/content/application~1json/schema",
            "obligations": [
              "DATEPARM vazio estabelece EOF antes do processamento das transações e produz relatório vazio: lines é [].",
              "diagnostics é obrigatório e contém strings.",
              "returnCode é opcional e não tem obrigação de ser zero.",
              "Nenhum mestre de conta, saldo ou transação é modificado."
            ]
          },
          {
            "status": 500,
            "schema": "#/components/schemas/ExecutionFailure",
            "obligations": [
              "Entrada vazia não exclui falhas verificadas de abertura ou fechamento.",
              "program e diagnostics são obrigatórios."
            ]
          }
        ]
      },
      "limitations": [
        "O resultado vazio é condicionado à conclusão da invocação; os arquivos ainda precisam estar acessíveis nos modos declarados.",
        "Não se atribui conteúdo aos datasets identificados pelos bindings.",
        "Este cenário não caracteriza o comportamento de transações vazias com DATEPARM não vazio."
      ]
    },
    {
      "id": "E1-2-reports-negative-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-reports"
      },
      "category": "negative",
      "purpose": "Distinguir um fluxo DATEPARM vazio permitido de um registro DATEPARM vazio inválido.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameters": [
            ""
          ],
          "crossReferenceFile": "CARDXREF",
          "transactionTypeFile": "TRANTYPE",
          "transactionCategoryFile": "TRANCATG"
        }
      },
      "expectedFromContract": {
        "requestConformance": "O item vazio viola minLength: 80; cada registro DATEPARM deve ter exatamente 80 caracteres.",
        "obligations": [
          "A permissão para array vazio não permite registros com comprimento zero.",
          "O contrato não especifica status ou schema de resposta para esta violação de request."
        ]
      },
      "limitations": [
        "Candidato deliberadamente inválido segundo o schema.",
        "Não se presume preenchimento automático de DATEPARM com espaços.",
        "Não se infere relatório vazio, execução COBOL ou resposta HTTP 400, 422 ou 500."
      ]
    }
  ]
}
